INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D13-TR-003', 'Campanhas que sugerem que a situação está sendo resolvida de forma lenta e incremental incomodam, porque não propõem solução concreta e não reconhecem a realidade vivida.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'afasta', NULL, NULL, NULL), ('D13-TR-015', 'A temática do dinheiro é vulnerável ao efeito "migalha": qualquer exagero ou pedido explícito de voto transforma alívio em propaganda.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'afasta', NULL, NULL, NULL), ('D13-TR-033', 'Mensagens que reconhecem apenas dificuldade financeira podem parecer incompletas diante de um cansaço que é também mental.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'cuidado e sobrecarga', 'afasta', NULL, NULL, NULL), ('D13-TR-260', 'A terceira rota frágil é rejeitada pela falta de credibilidade do ganho real anunciado.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'salário mínimo', 'afasta', NULL, NULL, NULL), ('D13-TR-265', 'A mesma especificidade que gera identificação em parte do público é lida por outra parte como argumento persuasivo demais, que parece usar a vulnerabilidade do trabalhador para convencer.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, NULL), ('D13-TR-266', 'A mudança de registro para linguagem de mérito e campanha no fechamento é lida como entonação vendedora.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'reconhecimento do trabalho', 'afasta', NULL, NULL, NULL), ('D13-TR-296', 'Sem valor concreto, a expressão juros mais baixos soa vaga, e a reação vai da dúvida à desconfiança de que seja bom demais para ser verdade.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'afasta', NULL, NULL, NULL), ('D13-TR-297', 'O fechamento que afirma que quem cuida do país cuida até do que parece pequeno soa como frase de efeito genérica, mesmo sem pedir voto.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, NULL), ('D13-TR-298', 'O fechamento que promete não ficar só no discurso é lido com ironia, já que a frase que ataca o discurso é sentida como discurso genérico.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, NULL), ('D13-TR-336', 'O diminutivo tem efeito reverso: em vez de suavizar, é lido como pesado e condescendente diante de um tema sentido com gravidade.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, NULL), ('D13-TR-337', 'A gíria usada soou forçada e não ressonante para quem tem salário fixo.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, NULL), ('D13-TR-339', 'Mesmo com a remoção do diminutivo e da gíria, a objeção de fundo sobre credibilidade do ganho tende a persistir sem prova concreta.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'salário mínimo', 'afasta', NULL, NULL, NULL), ('D01-TR-013-m25', 'Mais de 41 milhões de lares brasileiros são chefiados por mulheres; por gerenciarem o orçamento doméstico, são mais sensíveis aos impactos econômicos.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'contexto', NULL, NULL, '13'), ('D01-TR-023', 'A base do empreendedorismo feminino permanece formada em maioria por mulheres negras, mães e pertencentes às classes populares.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'mei e trabalho autônomo', 'contexto', NULL, NULL, '15'), ('D01-TR-024', 'A faixa de renda até cinco salários mínimos começará a sentir o impacto de medidas como a isenção do Imposto de Renda até R$ 5 mil e a redução até R$ 7 mil.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'impostos', 'contexto', NULL, NULL, '15'), ('D13-TR-075', 'O acesso citado inclui remédio de pressão, diabetes, asma, insulina, absorventes e fraldas geriátricas.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'saúde e sus', 'contexto', NULL, NULL, NULL), ('D13-TR-104', 'Os programas citados espontaneamente incluem Bolsa Família, farmácia popular, tarifa zero, Minha Casa Minha Vida, benefícios do MEI e licença-maternidade via MEI.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'atribuição de políticas públicas', 'contexto', NULL, NULL, NULL), ('D01-TR-030-m25', 'O engajamento nasce de caminho prático, nunca de slogan de superação.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '17'), ('D01-TR-040', 'Há sensação de melhoria quando algo reduz o risco financeiro.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'mei e trabalho autônomo', 'funciona', NULL, NULL, '18'), ('D01-TR-046-m25', 'Mostrar como um Estado presente pode ajudar no alívio do dia a dia por meio de políticas públicas.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '21'), ('D01-TR-047', 'Falar de controle do mês, não de dinheiro extra.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'impostos', 'funciona', NULL, NULL, '22'), ('D01-TR-048', 'Mostrar o que o dinheiro vira, não seu valor abstrato: comida, gás, remédio, escola; cada real vira cuidado.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'impostos', 'funciona', NULL, NULL, '22'), ('D01-TR-050', 'Reconhecer o aperto e o alívio real, por menor que seja, constrói confiança.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '22'), ('D13-TR-005', 'Citar benefícios concretos tem aceitação maior do que falar em proteção ou cuidado do país.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, NULL), ('D13-TR-007', 'As narrativas mais fortes partem da vida concreta: benefício acessível e claro, acesso garantido e programas já disseminados e conhecidos.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, NULL), ('D13-TR-076', 'A força da Farmácia Popular está na universalidade percebida: acesso descrito como simples, sem burocracia e igual independentemente de renda ou classe social.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'saúde e sus', 'funciona', NULL, NULL, NULL), ('D13-TR-235', 'Quanto mais concreto o número apresentado, mais crível a oferta; termo genérico soa bom demais para ser verdade.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, NULL), ('D13-TR-241', 'Recomenda-se trocar a reivindicação de mérito eleitoral pela explicação do mecanismo do benefício.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'reconhecimento do trabalho', 'funciona', NULL, NULL, NULL), ('D13-TR-246', 'Recomenda-se substituir a expressão genérica sobre juros mais baixos por uma taxa real.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, NULL), ('D13-TR-250', 'Recomenda-se incluir dado comparativo de ganho real acima da inflação ou trocar o argumento sobre salário mínimo.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'salário mínimo', 'funciona', NULL, NULL, NULL), ('D13-TR-262', 'Exemplos tangíveis como comida, remédio e respiro no fim do mês geram identificação imediata.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'impostos', 'funciona', NULL, NULL, NULL), ('D13-TR-263', 'O fechamento que reconhece um limite sem soar vazio, na chave de não é tudo mas é justo, é lido como honesto.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, NULL), ('D13-TR-264', 'O uso de substantivos concretos do campo semântico da sobrevivência dispensa interpretação sofisticada e exprime a intenção de forma direta.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, NULL), ('D13-TR-267', 'Recomenda-se reduzir a entonação de conquista e aumentar o viés de explicação: o que muda na prática, quando passa a valer e como confirmar o enquadramento na faixa.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'impostos', 'funciona', NULL, NULL, NULL), ('D13-TR-268', 'Recomenda-se substituir a reivindicação de mérito eleitoral por modos de verificar concretamente a validade do benefício.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'reconhecimento do trabalho', 'funciona', NULL, NULL, NULL), ('D13-TR-294', 'A ideia de crédito com juros mais baixos e sem garantia é lida como suporte real para quem está começando um negócio e gera vontade de pesquisar mais.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, NULL), ('D13-TR-295', 'A remoção do pedido de voto na versão revisada deixa a mensagem mais parecida com informação útil do que com propaganda.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, NULL), ('D13-TR-299', 'Recomenda-se testar a versão sem esse fechamento, deixando a mensagem terminar na informação prática.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, NULL), ('D13-TR-300', 'Recomenda-se falar de juros de modo mais concreto, deixando clara a diferença e o benefício, e explicar o acesso de maneira acessível.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, NULL), ('D13-TR-335', 'A ideia de conquista que não pode parar tem potencial por conectar a um sentimento de continuidade e trabalho em movimento que o público valoriza.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'salário mínimo', 'funciona', NULL, NULL, NULL), ('D13-TR-340', 'Recomenda-se incluir um comparativo real de ganho acima da inflação em determinado período para sustentar a alegação com dado.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, NULL), ('D13-TR-341', 'Como alternativa, recomenda-se abandonar o argumento de sobra no bolso, distante da realidade do público, e buscar aproximação por comparação histórica ou por ganho em outro benefício.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'salário mínimo', 'funciona', NULL, NULL, NULL), ('D13-TR-034', 'Aumenta o salário, aumenta tudo. Então dá no mesmo.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'salário mínimo', 'verbatim', NULL, NULL, NULL), ('D13-TR-133', 'é um sonho distante', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, NULL), ('D13-TR-134', 'dinheiro no bolso só existe se o bolso estiver furado', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, NULL), ('D13-TR-142', 'A isenção do imposto de renda mexe com a gente. Mostra que sabem quais são as nossas preocupações de verdade.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, NULL), ('D13-TR-207', 'De uns quatro, cinco anos para cá... a gente percebe que a situação foi só piorando tudo, ficando mais caro.', 'mulheres de 2 a 5 salários mínimos', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, NULL), ('D01-TR-034', 'Para trabalhadoras CLT, a queixa número um é o tempo: escala 6x1, jornada dupla, deslocamento e falta de folga.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '18'), ('D01-TR-039', 'Falta clareza sobre direitos: quanto contribuir, quanto vai render e o que fica garantido no futuro.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '18'), ('D01-TR-044', 'Para CLT, a crítica recai sobre a defasagem do salário mínimo frente à inflação, com a escala 6x1 como fator que rouba tempo sem compensar financeiramente.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'salário mínimo', 'achado', 'indício', NULL, '21'), ('D01-TR-045', 'Para MEI, o problema é a instabilidade: tem mês bom e mês ruim, sem garantias fixas.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '21'), ('D01-TR-068', 'A proteção ao trabalhador existe no discurso institucional, mas se dissolve diante da prática cotidiana: sobrecarga e desigualdade de gênero seguem sem resposta efetiva.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '27'), ('D01-TR-069', 'Para MEI, a proteção é algo conquistado sozinho, muitas vezes descoberto "por acaso".', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '28'), ('D01-TR-070', 'Para CLT, a proteção está vinculada à legislação, mas é percebida como insuficiente diante da sobrecarga real.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '28'), ('D01-TR-071', 'Grávidas são preteridas em processos seletivos.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '29'), ('D01-TR-072', 'Empresas evitam contratar mulheres por causa da licença-maternidade.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '29'), ('D01-TR-073', 'Canais de denúncia no trabalho são vistos como decorativos.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '29'), ('D01-TR-074', 'Há sobrecarga por enxugamento de quadro, sem aumento salarial correspondente.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '29'), ('D01-TR-075', 'A abordagem de saúde mental no trabalho é vista como superficial.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'saúde mental', 'achado', 'indício', NULL, '29'), ('D01-TR-103-m25', 'A vida chegou cedo demais, mas eles não deixaram de ser jovens: a juventude aparece menos como fase livre e mais como identidade comprimida por responsabilidades adultas.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '38'), ('D01-TR-104-m25', 'A rotina não é só corrida, ela consome o espaço de experimentar a juventude: trabalho, estudo, deslocamento e casa ocupam a maior parte da rotina, e o tempo livre aparece menos como lazer e mais como recuperação física e mental.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '38'), ('D03-TR-004', '5,3% da população trabalhou para aplicativos (transporte, entrega e similares) nos últimos 12 meses, com pouca variação entre as regiões (de 4,1% no Norte a 6,1% no Sul).', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '14'), ('D03-TR-005', 'Entre quem trabalhou para aplicativos nos últimos 12 meses, 45,5% atuou como motoboy. Essa proporção chega a 64,0% no Nordeste e 59,8% no Norte, contra 24,7% no Sul.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '14'), ('D03-TR-010-m25', 'Carreira, trabalho e sustento é citado por 6,1% como opção mais importante na vida hoje e por 17,9% somando primeira e segunda opções.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'renda e sustento', 'achado', 'indício', NULL, '16'), ('D03-TR-081-m25', 'O fim da escala 6 por 1 é conhecido por 67,3%, com avaliação de 59,3% ótima ou boa e 18,8% ruim ou péssima.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '76'), ('D12-TR-006', 'A narrativada proteção ao trabalhador precisa ir do "se virar sozinha" para ter condições de continuar.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '8'), ('D12-TR-007', 'A transformação vai da autonomia como abandono para a autonomia como potência: já se trabalha, cuida, vende, calcula e resolve, mas falta conjunção com tempo, descanso, informação, crédito, direitos e rede de segurança.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '8'), ('D12-TR-028', 'A palavra proteção é desejável, mas pouco suficiente.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, NULL), ('D12-TR-031', 'Para MEI e informais há autonomia, mas falta previsibilidade, orientação e segurança diante do imprevisto.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '10'), ('D12-TR-033', 'Resolver sozinha gera orgulho, mas também naturaliza abandono institucional.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '10'), ('D12-TR-034', 'Nas redes, o trabalho aparece entre orgulho e perrengue: coragem, liberdade possível, dupla jornada, crédito difícil, dúvidas sobre direitos e saúde mental.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '10'), ('D12-TR-035', 'Na escuta digital, empreendedoras trocam saberes e buscam orientação.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, '10'), ('D12-TR-036', 'Na escuta digital, trabalhadoras em escala 6x1 falam de maternidade, deslocamento, desgaste e falta de tempo.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '10'), ('D12-TR-037', 'As redes funcionam como apoio prático e emocional: ensina-se, pergunta-se e compartilha-se para tentar suprir a falta de orientação oficial.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'rede de apoio', 'achado', 'indício', NULL, '10'), ('D12-TR-044', 'Isotopia de esforço e autonomia: o trabalho dá orgulho e identidade, mas nasce da necessidade de se virar.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-045', 'Isotopia de sobrecarga e desamparo: a falta de proteção e de condições aparece no corpo, no tempo e no medo do imprevisto.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-047', 'Trabalhar, empreender e buscar renda aparecem como coragem, responsabilidade e tentativa de independência.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '12'), ('D12-TR-049', 'Para MEI e informais, a autonomia convive com instabilidade, ausência de rede e risco de adoecer, engravidar ou ficar sem renda.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '12'), ('D12-TR-056', 'O território "O direito explicado vira poder de agir" parte da ideia de que informação clara transforma direito desconhecido em acesso possível, com força entre MEI e informais.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '13'), ('D12-TR-060', 'O território "Autonomia com rede de segurança" parte da ideia de que autonomia precisa vir com garantia, orientação, crédito e proteção no imprevisto, com força entre MEI e informais.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '13'), ('D12-TR-063', 'A tensão central não está entre mulher protegida e desprotegida, mas entre autonomia como abandono e autonomia como potência.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-064', 'A autonomia opera em estado de falta: há trabalho, cuidado, venda, cálculo, aprendizado e resolução de problemas, mas sem tempo, descanso, previsibilidade, informação suficiente ou rede de proteção.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-065', 'O objeto de valor são condições para continuar: tempo próprio, descanso, renda mais previsível, orientação clara, crédito acessível, direitos compreendidos, proteção no imprevisto e possibilidade de planejar.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-066', 'No estado final, o protagonismo se mantém sem a necessidade de sustentar tudo sozinha: trabalho com menos improviso, cuidado sem anulação, acesso a direitos e recuperação de margem.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-067', 'O trabalho, o corre e a capacidade de se virar são valorizados, mas essa autonomia perde potência quando precisa substituir a proteção institucional.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-068', 'O ponto de partida é um estado de falta, disjunto das condições que tornam o trabalho sustentável.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-070', 'A transformação em jogo vai do "se virar sozinha" para ter condições de continuar.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '14'), ('D12-TR-072', 'A mulher aparece como sujeito competente que trabalha, cuida, resolve e sustenta, mas não deveria carregar tudo sozinha.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '15'), ('D12-TR-074', 'O corre é vivido como obrigação solitária.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '15'), ('D12-TR-076', 'No estado final, o corre deixa de ser só sobrevivência e pode virar caminho de futuro.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'futuro possível', 'achado', 'indício', NULL, '15'), ('D12-TR-077', 'Direito pouco entendido não protege: a proteção começa quando a informação vira caminho acessível.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '16'), ('D12-TR-078', 'A mulher aparece como sujeito que busca, aprende, compara e decide, mas precisa de clareza para agir.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '16'), ('D12-TR-080', 'O direito existe, mas parece distante, confuso ou inacessível.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '16'), ('D12-TR-082', 'No estado final, torna-se possível acessar, cobrar, planejar e decidir com mais segurança.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'informação sobre direitos', 'achado', 'indício', NULL, '16'), ('D12-TR-084', 'A trabalhadora sustenta a casa, mas também precisa de tempo próprio e de saúde mental preservada.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-086', 'O trabalho consome tempo, corpo e vida familiar.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-088', 'No estado final, trabalhar deixa de significar se anular e passa a permitir alguma qualidade de vida.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '17'), ('D12-TR-089', 'Para MEI e informais, autonomia só vira potência quando existe proteção no imprevisto.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '18'), ('D12-TR-090', 'A empreendedora ou trabalhadora autônoma se vira, mas precisa de garantia para não ficar desamparada.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '18'), ('D12-TR-092', 'A autonomia depende do improviso e vira medo quando algo sai do controle.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '18'), ('D12-TR-094', 'No estado final, a autonomia se mantém com mais segurança para trabalhar, cuidar e planejar.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '18'), ('D12-TR-254', 'O sujeito desta análise não parte da passividade, mas da sobrecarga: já trabalha, cuida, compara, calcula e decide.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '42'), ('D12-TR-255', 'O que falta é a conjunção com condições que tornem essa competência menos solitária e mais potente.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'autonomia e amparo', 'achado', 'indício', NULL, '42'), ('D13-TR-004', 'Aquilo que é percebido como "de direito" nem sempre é lido como benefício, e sim como cumprimento do mínimo.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-006', 'As políticas públicas integram o cotidiano sem serem lembradas espontaneamente, e a percepção dos benefícios é escassa ou pouco associada a um governo ou período específico.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'atribuição de políticas públicas', 'achado', 'indício', NULL, NULL), ('D13-TR-012', 'A intensidade da vida cotidiana não deixa tempo nem dinheiro para descanso e para a aspiração de uma vida melhor.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, NULL), ('D13-TR-025', 'Entre os participantes deste estudo, a exaustão prevalece em todos os grupos e a vida segue sem tempo para pausas.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, NULL), ('D13-TR-027', 'Ser MEI ou trabalhar em home office não significa trabalhar menos, apenas gerenciar o tempo de outra maneira e seguir exausta.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, NULL), ('D13-TR-029', 'A ausência de rede de apoio levou parte do público a deixar o vínculo formal para empreender por conta própria, mesmo sem clareza sobre como se organizaria.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'mei e trabalho autônomo', 'achado', 'indício', NULL, NULL), ('D13-TR-041', 'Tanto o vínculo formal quanto o negócio próprio exigem muito esforço, mas cobram preços diferentes.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-042', 'Entre os participantes deste estudo com vínculo formal, a queixa principal é a falta de tempo, com escala 6x1, jornada dupla, deslocamento e ausência de folga aparecendo em quase todos os relatos espontâneos sobre rotina.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, NULL), ('D13-TR-043', 'No regime formal há um pouco mais de segurança, mas não absoluta.', 'mulheres de 2 a 5 salários mínimos', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, NULL), ('D13-TR-044', 'Entre microempreendedoras, o problema central é a instabilidade: ausência de renda fixa e de rede